"""Core data model and stowage rules for a single ferry crossing."""

from dataclasses import dataclass
from typing import Tuple


@dataclass
class Vehicle:
    plate: str
    weight_kg: float
    height_m: float
    priority_tier: int  # 1 = reserved/commercial, 2 = standard booking, 3 = standby
    arrival_order: int


@dataclass
class Lane:
    name: str
    capacity_kg: float
    clearance_m: float
    current_load_kg: float = 0.0

    def remaining_capacity_kg(self) -> float:
        return self.capacity_kg - self.current_load_kg


def fits(vehicle: Vehicle, lane: Lane) -> bool:
    """Return True if the vehicle can be safely stowed in the lane."""
    if vehicle.height_m > lane.clearance_m:
        return False
    if vehicle.weight_kg > lane.remaining_capacity_kg():
        return False
    return True


def load_vehicle(vehicle: Vehicle, lane: Lane) -> None:
    lane.current_load_kg += vehicle.weight_kg


def choose_target_lane(bow_lane: Lane, stern_lane: Lane) -> Tuple[Lane, Lane]:
    """Pick which of a matched bow/stern lane pair should take the next vehicle.

    Returns the chosen lane first and the alternate lane second, so the
    caller can fall back to the alternate if the chosen one can't fit
    the vehicle being placed.
    """
    if bow_lane.current_load_kg > stern_lane.current_load_kg:
        return bow_lane, stern_lane
    return stern_lane, bow_lane

"""Assigns queued vehicles to bow/stern lane pairs for a ferry crossing."""

from typing import List

from vessel import Vehicle, Lane, fits, load_vehicle, choose_target_lane


def sort_queue(vehicles: List[Vehicle]) -> List[Vehicle]:
    """Board reserved/commercial traffic first, then standard, then standby."""
    return sorted(vehicles, key=lambda v: (v.priority_tier, v.arrival_order))


def plan_load(vehicles: List[Vehicle], bow_lanes: List[Lane], stern_lanes: List[Lane]) -> List[Vehicle]:
    """Walk the boarding queue and assign each vehicle to a lane.

    Returns the vehicles that could not be placed on this crossing.
    """
    unassigned = []
    for vehicle in sort_queue(vehicles):
        assigned = False
        for bow_lane, stern_lane in zip(bow_lanes, stern_lanes):
            target, other = choose_target_lane(bow_lane, stern_lane)
            if fits(vehicle, target):
                load_vehicle(vehicle, target)
                assigned = True
                break
            if fits(vehicle, other):
                load_vehicle(vehicle, other)
                assigned = True
                break
        if not assigned:
            unassigned.append(vehicle)
    return unassigned


def summarize(bow_lanes: List[Lane], stern_lanes: List[Lane]) -> List[str]:
    lines = []
    for lane in [*bow_lanes, *stern_lanes]:
        lines.append(f"{lane.name}: {lane.current_load_kg:.0f} / {lane.capacity_kg:.0f} kg")
    return lines


if __name__ == "__main__":
    queue = [
        Vehicle("AB-1234", 1800, 1.6, priority_tier=2, arrival_order=1),
        Vehicle("TRK-901", 9200, 3.4, priority_tier=1, arrival_order=2),
        Vehicle("CD-5678", 1500, 1.5, priority_tier=2, arrival_order=3),
        Vehicle("VAN-042", 2600, 2.1, priority_tier=1, arrival_order=4),
        Vehicle("EF-9012", 1400, 1.5, priority_tier=3, arrival_order=5),
    ]
    bow = [Lane("bow-1", capacity_kg=12000, clearance_m=4.5)]
    stern = [Lane("stern-1", capacity_kg=12000, clearance_m=4.5)]

    leftover = plan_load(queue, bow, stern)
    for line in summarize(bow, stern):
        print(line)
    if leftover:
        print(f"{len(leftover)} vehicle(s) held for the next sailing")
